                if idxs is None:
                    return ''
                if '..' in inside:
                    selected=[fields[i] for i in idxs if 0<=i<n]
                else:
                    v=idxs[0]
                    idx=v-1 if v>0 else n+v
                    if 0<=idx<n:
                        selected=[fields[idx]]
                    else:
                        selected=[]
                if delimiter is None:
                    delim_join=' '
                else:
                    if delimiter==',':
                        delim_join=','
                    elif delimiter==':':
                        delim_join=':'
                    else:
                        delim_join=' '
                return delim_join.join(selected)
            except:
                return ''
        res=re.sub(r'\{([^{}]+)\}', repl, tmpl)
        return res
    else:
        fields=split_fields(line, delimiter)
        n=len(fields)
        selected=[]
        for expr in val:
            try:
                idxs=eval_index_expr(expr, n)
                if idxs is None:
                    continue
                if '..' in expr:
                    for i in idxs:
                        if 0<=i<n:
                            selected.append(fields[i])
                else:
                    v=idxs[0]
                    idx=v-1 if v>0 else n+v
                    if 0<=idx<n:
                        selected.append(fields[idx])
            except ValueError as e:
                raise
        if delimiter is None:
            return ' '.join(selected)
        else:
            if delimiter==',':
                return ','.join(selected)
            elif delimiter==':':
                return ':'.join(selected)
            else:
                return ' '.join(selected)

def parse_args(arg_list, prefix):
    opts={}
    i=0
    while i < len(arg_list):
        arg=arg_list[i]
        if arg=='--':
            i+=1
            continue
        if arg.startswith('--'):
            if '=' in arg:
                name,val=arg.split('=',1)
                name=name[2:]
            else:
                name=arg[2:]
                val=None
            if name in REQ_OPTS:
                if val is None:
                    if i+1 < len(arg_list) and not arg_list[i+1].startswith('-'):
                        val=arg_list[i+1]
                        i+=1
                    else:
                        msg=MISSING_MSGS.get(name, f"{name} required")
                        error_exit(msg, prefix)
                opts[name]=val
                if name=='scheme':
                    if val not in ('default','path','history'):
                        error_exit(f"invalid scoring scheme: {val} (expected: default|path|history)", prefix)
                elif name=='tiebreak':
                    allowed=set(['length','chunk','pathname','begin','end','index'])
                    for p in val.split(','):
                        if p not in allowed:
                            error_exit(f"invalid sort criterion: {p}", prefix)
                elif name in ('nth','with-nth','accept-nth'):
                    try:
                        if '{' not in val:
                            for expr in val.split(','):
                                expr=expr.strip()
                                if expr=='':
                                    raise ValueError(f"invalid format: {expr}")
                                eval_index_expr(expr, 5)
                    except ValueError as e:
                        error_exit(str(e), prefix)
                elif name=='delimiter':
                    if val=='':
                        error_exit("delimiter required", prefix)
                elif name=='expect':
                    if val=='':
                        error_exit("key names required", prefix)
            elif name in BOOL_OPTS:
                if name in OPTIONAL_OPTS:
                    if val is None and i+1 < len(arg_list) and not arg_list[i+1].startswith('-'):
                        # consume next as value for optional
                        # but only if next not looking like another option requiring value?
                        # For now consume
                        val_next=arg_list[i+1]
                        opts[name]=val_next
                        i+=1
                    else:
                        opts[name]= True if val is None else val
                else:
                    opts[name]=True
            elif name in OPTIONAL_OPTS:
                if val is None:
                    if i+1 < len(arg_list) and not arg_list[i+1].startswith('-'):
                        val=arg_list[i+1]
                        i+=1
                        opts[name]=val
                    else:
                        opts[name]=True
                else:
                    opts[name]=val
            else:
                error_exit(f"unknown option: --{name}", prefix)
        elif arg.startswith('+') and len(arg)>=2:
            code=arg[1:]
            # handle like +i, +s, +x etc. Could be multiple chars? e.g., +s? We'll handle first char, if more then iterate
            handled=False
            for c in code:
                if c in PLUS_MAP:
                    opts[PLUS_MAP[c]]=True
                    handled=True
                else:
                    error_exit(f"unknown option: +{c}", prefix)
            if not handled:
                error_exit(f"unknown option: {arg}", prefix)
        elif arg.startswith('-') and len(arg)>1:
            chars=arg[1:]
            j=0
            consumed=False
            while j < len(chars):
                c=chars[j]
                if c not in SHORT_MAP and c not in ('e','i','x','s','n','d','m','q','f','1','0'):
                    error_exit(f"unknown option: -{c}", prefix)
                name=SHORT_MAP.get(c)
                if name is None:
                    if c=='x':
                        name='extended'
                    elif c=='s':
                        name='no-sort'
                    else:
                        name=c
                if c in SHORT_REQ:
                    val=None
                    if j+1 < len(chars):
                        val=chars[j+1:]
                        j=len(chars)
                    else:
                        if i+1 < len(arg_list):
                            val=arg_list[i+1]
                            i+=1
                        else:
                            msg=MISSING_MSGS.get(name, "query string required" if name in ('query','filter') else f"{name} required")
                            error_exit(msg, prefix)
                    opts[name]=val
                    if name in ('nth','with-nth','accept-nth'):
                        try:
                            if '{' not in val:
                                for expr in val.split(','):
                                    expr=expr.strip()
                                    if expr=='':
                                        raise ValueError(f"invalid format: {expr}")
                                    eval_index_expr(expr,5)
                        except ValueError as e:
                            error_exit(str(e), prefix)
                    consumed=True
                    break
                elif c=='m':
                    val=True
                    if j+1 < len(chars):
                        val=chars[j+1:]
                        j=len(chars)
                    opts[name]=val
                    consumed=True
                    break
                else:
                    opts[name]=True
                    j+=1
            # need to handle case where we consumed via break? already
        else:
            opts.setdefault('_positional',[]).append(arg)
        i+=1
    return opts

def main():
    file_path=os.environ.get('FZF_DEFAULT_OPTS_FILE','')
    file_opts={}
    if file_path:
        if not os.path.isfile(file_path):
            sys.stderr.write(f"$FZF_DEFAULT_OPTS_FILE: open {file_path}: no such file or directory\n")
            sys.exit(2)
        try:
            content=open(file_path,'r',encoding='utf-8').read()
        except:
            sys.stderr.write(f"$FZF_DEFAULT_OPTS_FILE: open {file_path}: no such file or directory\n")
            sys.exit(2)
        if content.strip():
            try:
                file_args=shlex.split(content, posix=True)
            except:
                file_args=content.split()
            file_opts=parse_args(file_args, file_path)
    env_val=os.environ.get('FZF_DEFAULT_OPTS','')
    env_opts={}
    if env_val:
        try:
            env_args=shlex.split(env_val, posix=True)
        except:
            env_args=env_val.split()
        env_opts=parse_args(env_args, "$FZF_DEFAULT_OPTS")
    cmd_args=sys.argv[1:]
    cmd_opts=parse_args(cmd_args, None)
    opts={}
    for d in (file_opts, env_opts, cmd_opts):
        for k,v in d.items():
            if k=='_positional':
                opts.setdefault('_positional', []).extend(v)
            else:
                opts[k]=v
    if 'help' in opts:
        sys.stdout.write(HELP_TEXT)
        sys.exit(0)
    if 'version' in opts:
        sys.stdout.write(VERSION_TEXT)
        sys.exit(0)
    if 'bash' in opts:
        sys.stdout.write(BASH_TEXT)
        sys.exit(0)
    if 'zsh' in opts:
        sys.stdout.write(ZSH_TEXT)
        sys.exit(0)
    if 'fish' in opts:
        sys.stdout.write(FISH_TEXT)
        sys.exit(0)
    if 'man' in opts:
        try:
            result=subprocess.run(['man','fzf'], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=5)
            if result.returncode==0:
                sys.stdout.write(result.stdout)
                sys.exit(0)
            else:
                if result.stderr:
                    sys.stdout.write(result.stderr)
                elif result.stdout:
                    sys.stdout.write(result.stdout)
                else:
                    sys.stdout.write("This system has been minimized by removing packages and content that are\nnot required on a system that users do not log into.\n\nTo restore this content, including manpages, you can run the 'unminimize'\ncommand. You will still need to ensure the 'man-db' package is installed.\n")
                sys.exit(0)
        except FileNotFoundError:
            sys.stdout.write("This system has been minimized by removing packages and content that are\nnot required on a system that users do not log into.\n\nTo restore this content, including manpages, you can run the 'unminimize'\ncommand. You will still need to ensure the 'man-db' package is installed.\n")
            sys.exit(0)
        except Exception:
            sys.stdout.write("This system has been minimized by removing packages and content that are\nnot required on a system that users do not log into.\n\nTo restore this content, including manpages, you can run the 'unminimize'\ncommand. You will still need to ensure the 'man-db' package is installed.\n")
            sys.exit(0)
    filter_query=None
    if 'filter' in opts:
        filter_query=opts['filter']
        if filter_query is True:
            filter_query=''
    is_filter_mode = filter_query is not None
    if is_filter_mode:
        query=filter_query if filter_query is not None else ''
        exact='exact' in opts
        ignore_case='ignore-case' in opts
        no_ignore_case='no-ignore-case' in opts
        extended=True
        if 'no-extended' in opts:
            extended=False
        tiebreak=opts.get('tiebreak','length')
        scheme=opts.get('scheme','default')
        no_sort='no-sort' in opts
        literal='literal' in opts
        ansi='ansi' in opts
        tac='tac' in opts
        tail_val=opts.get('tail',None)
        read0='read0' in opts
        print0='print0' in opts
        print_query='print-query' in opts
        delimiter=opts.get('delimiter',None)
        nth_spec=None
        if 'nth' in opts:
            nth_val=opts['nth']
            if not isinstance(nth_val, bool):
                try:
                    nth_spec=parse_nth_spec(str(nth_val))
                except:
                    nth_spec=None
        with_nth_spec=None
        if 'with-nth' in opts:
            wn=opts['with-nth']
            if not isinstance(wn, bool):
                try:
                    with_nth_spec=parse_nth_spec(str(wn))
                except:
                    with_nth_spec=None
        accept_nth_spec=None
        if 'accept-nth' in opts:
            an=opts['accept-nth']
            try:
                accept_nth_spec=parse_nth_spec(str(an))
            except:
                accept_nth_spec=None
        data=sys.stdin.buffer.read()
        lines=[]
        if read0:
            if data:
                parts=data.split(b'\x00')
                for p in parts:
                    if p==b'' and p is parts[-1] and data.endswith(b'\x00'):
                        continue
                    try:
                        s=p.decode('utf-8', errors='replace')
                    except:
                        s=p.decode('latin-1')
                    lines.append(s)
        else:
            text=data.decode('utf-8', errors='replace')
            if text=='':
                lines=[]
            else:
                raw=text.split('\n')
                if text.endswith('\n'):
                    raw=raw[:-1]
                lines=raw
        if tail_val is not None:
            try:
                n=int(tail_val)
                if n < len(lines):
                    lines=lines[-n:]
            except:
                pass
        if tac:
            lines=list(reversed(lines))

        # helpers defined inner for query handling
        def is_case_sensitive_global(q):
            if ignore_case:
                return False
            if no_ignore_case:
                return True
            for ch in q:
                if ch.isupper():
                    return True
            return False
        global_case_sensitive=is_case_sensitive_global(query)
        def strip_ansi_local(s):
            return re.sub(r'\x1b\[[0-9;]*m','',s)
        def normalize(s):
            if literal:
                return s
            n=unicodedata.normalize('NFKD', s)
            return ''.join(c for c in n if not unicodedata.combining(c))
        def get_searchable(line):
            base=line
            if with_nth_spec is not None:
                try:
                    transformed=extract_fields(base, delimiter, with_nth_spec)
                    # handle {n} placeholder need index: we handle per idx later, but for now if template contains {n}, keep placeholder
                    base=transformed
                except:
                    base=line
            if nth_spec is not None:
                try:
                    searchable=extract_fields(base, delimiter, nth_spec)
                except:
                    searchable=base
            else:
                searchable=base
            if ansi:
                searchable=strip_ansi_local(searchable)
            return searchable

        def parse_query_terms(q):
            if not extended:
                return [q] if q!='' else []
            if q=='':
                return []
            tokens=[]
            cur=''
            i=0
            escaping=False
            while i<len(q):
                ch=q[i]
                if escaping:
                    if ch==' ':
                        cur+=' '
                    else:
                        cur+='\\'+ch
                    escaping=False
                else:
                    if ch=='\\' and i+1<len(q) and q[i+1]==' ':
                        escaping=True
                    elif ch==' ':
                        if cur!='':
                            tokens.append(cur)
                            cur=''
                    else:
                        cur+=ch
                i+=1
            if cur!='':
                tokens.append(cur)
            return [t for t in tokens if t!='']

        query_terms=parse_query_terms(query) if query else []

        def term_to_matcher(term):
            is_inverse=False
            t=term
            if t.startswith('!'):
                is_inverse=True
                t=t[1:]
                if t=='':
                    return (is_inverse,'empty','')
            is_exact=False
            is_fuzzy=False
            is_prefix=False
            is_suffix=False
            if exact:
                if t.startswith("'"):
                    t=t[1:]
                    is_fuzzy=True
                else:
                    is_exact=True
                    if t.startswith('^'):
                        is_prefix=True
                        t=t[1:]
                    if t.endswith('$') and len(t)>0:
                        is_suffix=True
                        t=t[:-1]
            else:
                if t.startswith("'"):
                    is_exact=True
                    t=t[1:]
                else:
                    if t.startswith('^'):
                        is_exact=True
                        is_prefix=True
                        t=t[1:]
                    if t.endswith('$') and len(t)>0:
                        is_exact=True
                        is_suffix=True
                        t=t[:-1]
                    if not is_exact:
                        is_fuzzy=True
            mode=None
            if is_exact:
                if is_prefix and is_suffix:
                    mode='prefix_suffix_exact'
                elif is_prefix:
                    mode='prefix_exact'
                elif is_suffix:
                    mode='suffix_exact'
                else:
                    mode='exact'
            elif is_fuzzy:
                mode='fuzzy'
            else:
                mode='fuzzy'
            return (is_inverse, mode, t)

        has_or='|' in query_terms
        if has_or:
            groups=[]
            cur=[]
            for tok in query_terms:
                if tok=='|':
                    if cur:
                        groups.append(cur)
                        cur=[]
                else:
                    cur.append(tok)
            if cur:
                groups.append(cur)
            matchers_groups=[]
            for grp in groups:
                matchers_groups.append([term_to_matcher(t) for t in grp])
            single_matchers=None
        else:
            if query_terms:
                single_matchers=[term_to_matcher(t) for t in query_terms]
            else:
                single_matchers=[]
            matchers_groups=None

        def matches_exact(pat, txt, mode, case_sensitive, literal_flag):
            if not literal_flag:
                pat_n=normalize(pat)
                txt_n=normalize(txt)
            else:
                pat_n=pat
                txt_n=txt
            if not case_sensitive:
                pat_n=pat_n.lower()
                txt_n=txt_n.lower()
            if mode=='exact':
                return pat_n in txt_n
            elif mode=='prefix_exact':
                return txt_n.startswith(pat_n)
            elif mode=='suffix_exact':
                return txt_n.endswith(pat_n)
            elif mode=='prefix_suffix_exact':
                return txt_n==pat_n
            return False

        def subsequence_match(pat, txt):
            pi=0
            for ch in txt:
                if pi < len(pat) and ch==pat[pi]:
                    pi+=1
                    if pi==len(pat):
                        return True
            return pi==len(pat)

        def matches_fuzzy(pat, txt, case_sensitive, literal_flag):
            if not literal_flag:
                pat_n=normalize(pat)
                txt_n=normalize(txt)
            else:
                pat_n=pat
                txt_n=txt
            if not case_sensitive:
                pat_n=pat_n.lower()
                txt_n=txt_n.lower()
            if pat_n=='':
                return True
            return subsequence_match(pat_n, txt_n)

        def compute_fuzzy_score(pat, txt, scheme_local, case_sensitive, literal_flag):
            # simple scoring: 16 per char + bonuses
            if not literal_flag:
                pat_n=normalize(pat)
                txt_n=normalize(txt)
            else:
                pat_n=pat
                txt_n=txt
            if not case_sensitive:
                pat_n=pat_n.lower()
                txt_n=txt_n.lower()
            if pat_n=='':
                return 0
            # find best subsequence alignment with max score
            # We'll brute force with DP scoring similar to earlier
            n=len(pat_n); m=len(txt_n)
            NEG=-10**9
            # bonus array
            bonus=[]
            for pos in range(m):
                if pos==0:
                    b=8
                elif txt[pos-1]=='/':
                    b=8 if scheme_local in ('default','path') else 0
                elif scheme_local=='default' and txt[pos-1] in ' -_':
                    b=4
                else:
                    b=0
                bonus.append(b)
            # dp
            dp=[[NEG]*(m+1) for _ in range(n+1)]
            for j in range(m+1):
                dp[0][j]=0
            for i in range(1,n+1):
                for j in range(1,m+1):
                    # skip
                    best=dp[i][j-1]-1  # gap penalty
                    if pat_n[i-1]==txt_n[j-1]:
                        prev=dp[i-1][j-1]
                        if prev!=NEG:
                            b=bonus[j-1]
                            consec=0
                            if i>1 and j>1 and pat_n[i-2]==txt_n[j-2]:
                                # check if previous was consecutive (approx)
                                # if dp[i-1][j-1] > dp[i-1][j-2]-1 then it came from match
                                if dp[i-1][j-1] != dp[i-1][j-2]-1:
                                    consec=5
                            cand=prev+16+b+consec
                            if cand>best:
                                best=cand
                    dp[i][j]=best
            return dp[n][m]

        # Determine tiebreak list
        if 'tiebreak' not in opts:
            if scheme=='path':
                tb_list=['pathname','length']
            elif scheme=='history':
                tb_list=['index']
            else:
                tb_list=['length']
        else:
            tb_val=opts.get('tiebreak','length')
            tb_list=[c.strip() for c in tb_val.split(',') if c.strip()]

        matched=[]
        for idx, original_line in enumerate(lines):
            searchable=get_searchable(original_line)
            # Replace {n} in searchable if needed? For with-nth that contained {n}, we kept placeholder; now replace
            if with_nth_spec is not None and with_nth_spec[0]=='template' and '{n}' in searchable:
                searchable=searchable.replace('{n}', str(idx))
            if not query_terms:
                # empty query matches all
                score=0
                matched.append((original_line, searchable, idx, score))
                continue
            line_match=False
            score=0
            if has_or:
                for group in matchers_groups:
                    group_ok=True
                    group_score=0
                    for (is_inv, mode, pat) in group:
                        if mode=='empty':
                            group_ok=False
                            break
                        if pat=='':
                            term_match=True
                        else:
                            if mode=='fuzzy':
                                term_match=matches_fuzzy(pat, searchable, global_case_sensitive, literal)
                            else:
                                term_match=matches_exact(pat, searchable, mode, global_case_sensitive, literal)
                        if is_inv:
                            term_match=not term_match
                        if not term_match:
                            group_ok=False
                            break
                        if not is_inv and mode=='fuzzy' and term_match:
                            try:
                                group_score+=compute_fuzzy_score(pat, searchable, scheme, global_case_sensitive, literal)
                            except:
                                group_score+=len(pat)
                    if group_ok:
                        line_match=True
                        score=group_score
                        break
            else:
                all_match=True
                total_score=0
                for (is_inv, mode, pat) in single_matchers:
                    if mode=='empty':
                        all_match=False
                        break
                    if pat=='':
                        term_match=True
                    else:
                        if mode=='fuzzy':
                            term_match=matches_fuzzy(pat, searchable, global_case_sensitive, literal)
                        else:
                            term_match=matches_exact(pat, searchable, mode, global_case_sensitive, literal)
                    if is_inv:
                        term_match=not term_match
                    if not term_match:
                        all_match=False
                        break
                    if not is_inv and mode=='fuzzy' and term_match:
                        try:
                            total_score+=compute_fuzzy_score(pat, searchable, scheme, global_case_sensitive, literal)
                        except:
                            total_score+=len(pat)
                if all_match:
                    line_match=True
                    score=total_score
            if line_match:
                matched.append((original_line, searchable, idx, score))

        # Sorting
        if not no_sort and matched:
            # define key for tiebreak
            # Precompute metrics for each entry
            def pathname_of(s):
                # after last '/'
                if '/' in s:
                    return s.rsplit('/',1)[-1]
                return s
            def begin_pos(pat, txt, case_sensitive, literal_flag):
                # earliest start of fuzzy match
                if not literal_flag:
                    pat_n=normalize(pat)
                    txt_n=normalize(txt)
                else:
                    pat_n=pat
                    txt_n=txt
                if not case_sensitive:
                    pat_n=pat_n.lower()
                    txt_n=txt_n.lower()
                # find first occurrence subsequence start
                # brute force find earliest start index
                n=len(pat_n); m=len(txt_n)
                # For each possible start position of first char, try to match
                for start in range(m):
                    if txt_n[start]!=pat_n[0]:
                        continue
                    # try to match sequentially
                    pi=1
                    ti=start+1
                    while pi<n and ti<m:
                        if txt_n[ti]==pat_n[pi]:
                            pi+=1
                        ti+=1
                    if pi==n and txt_n[start]==pat_n[0]:
                        # need also ensure full match possible from start
                        # Check subsequence from start
                        pi=0
                        for ti2 in range(start, m):
                            if txt_n[ti2]==pat_n[pi]:
                                pi+=1
                                if pi==n:
                                    return start
                return m
            def end_pos(pat, txt, case_sensitive, literal_flag):
                if not literal_flag:
                    pat_n=normalize(pat)
                    txt_n=normalize(txt)
                else:
                    pat_n=pat
                    txt_n=txt
                if not case_sensitive:
                    pat_n=pat_n.lower()
                    txt_n=txt_n.lower()
                # find last index of match
                # brute force find last match position
                # reverse search
                pi=len(pat_n)-1
                for i in range(len(txt_n)-1, -1, -1):
                    if txt_n[i]==pat_n[pi]:
                        pi-=1
                        if pi<0:
                            return i
                return -1
            # For sorting we need to compute for each entry the begin/end for first fuzzy term? Use first fuzzy pattern in query
            first_fuzzy_pat=None
            for (is_inv, mode, pat) in (single_matchers if single_matchers else []):
                if mode=='fuzzy' and not is_inv:
                    first_fuzzy_pat=pat
                    break
            if has_or and not first_fuzzy_pat:
                # try groups
                for grp in matchers_groups or []:
                    for (is_inv, mode, pat) in grp:
                        if mode=='fuzzy' and not is_inv:
                            first_fuzzy_pat=pat
                            break
                    if first_fuzzy_pat:
                        break
            def sort_key(entry):
